-- Cedars Art Production — import 170 archive titles
-- Source: sabbah_full_archive.json
-- Notes:
--   * Archive carries no year, synopsis, genres or cast — those columns stay empty.
--   * All titles are Latin script; ar/en/fr all seeded with the same string so the
--     Arabic UI shows the title instead of an empty box. Replace ar values later.
--   * First 15 rows get is_featured_slider = true so the hero marquee has content.
--   * Re-runnable: on conflict updates the row instead of failing.

on conflict (slug) do update set
  title = excluded.title,
  seasons_count = excluded.seasons_count,
  poster_url = excluded.poster_url,
  trailer_url = excluded.trailer_url,
  status = excluded.status,
  is_featured_slider = excluded.is_featured_slider,
  sort_order = excluded.sort_order;

select public.rebuild_search_index() as indexed_rows;

select count(*) as series_rows,
       count(*) filter (where is_featured_slider) as featured
from public.series;
